"""Rebuild the readable report from the checked JSON register."""
import json
from pathlib import Path
from stage1 import ROOT, sha256, validate_spec

spec_path = ROOT / 'data/house_spec.json'
spec = json.loads(spec_path.read_text())
errors = validate_spec(spec)
if errors:
    raise ValueError(errors)
data_check = json.loads((ROOT / 'data/data_validation.json').read_text())
scene_check = json.loads((ROOT / 'data/scene_validation.json').read_text())
if not data_check['ok'] or not scene_check['ok']:
    raise ValueError('Validation failed')
if any(record['spec_sha256'] != sha256(spec_path) for record in (data_check, scene_check)):
    raise ValueError('Validation is stale: spec changed')
if scene_check['scene_sha256'] != sha256(ROOT / 'models/house_stage1.blend'):
    raise ValueError('Validation is stale: scene changed')
measurements = {m['id']: m for m in spec['measurements']}
labels = spec['assumptions_policy']['status_labels']
lines = ['# Этап 1 — подготовка данных и шаблона', '',
         'Реализован 10 октября 2026 года по указанию пользователя «реализуй план». Объём: подготовка исходных данных и пустой сцены. Построение дома начинается с этапа 2.', '',
         '## Результат', '',
         '- `house_spec.json`: 118 параметров, 12 строк экспликации, исходный дом отдельно от альтернатив и допущений.',
         '- `../models/house_stage1.blend`: пустая редактируемая сцена Blender 5.2.1 LTS; метрическая система, 1 единица = 1 метр.',
         '- `stage1_plan.md`: принятый план; `data_validation.json` и `scene_validation.json`: результаты проверок.',
         '- `../scripts/`: проверка реестра, создание/проверка сцены, обновление этого отчёта; `../tests/`: проверки ошибок данных.', '',
         '## Что подтверждено', '',
         'Основной прямоугольник 12000 × 10000 мм. Кухня-гостиная справа внизу: 5000 × 5300 мм. Гараж слева вверху: 5800 × 3500 мм. Конёк исходной крыши принят +5320 мм. Размеры и номера страниц приведены ниже.', '',
         'Начало координат — нижний левый наружный угол главного прямоугольника. X вправо по плану, Y вверх по плану, Z вверх. Чистый пол Z=0. Числа длин хранятся в миллиметрах; передача в Blender через деление на 1000.', '',
         '## Неопределённости и порядок их проверки', '',
         '**Реестр не является готовой координатной моделью стен.** На плане отсутствуют номера помещений. Привязка десяти названий экспликации и точных косяков требует проверки при построении базовой модели. Эти сведения не выданы за подтверждённые.', '']
for issue in spec['unresolved']:
    lines += [f"- **{issue['id']}**: {issue['issue']} {issue['resolve_before']}"]
lines += ['', 'Ширины 12 неподписанных дверей — визуальные предварительные оценки по плану, округлённые до 50 мм. Диапазон ±50 мм задаёт сценарий проверки чувствительности, а не точность обмера. Положение косяков и открывание необходимо перенести с PDF до построения проёмов. Если пригодность лестницы зависит от неподтверждённого размера, показывать её как условную и уточнять размер до детализации.', '',
          '## Предварительные конструкции', '',
          '| Параметр | Основной габарит | Проверка увеличения |', '|---|---:|---:|',
          '| Крыша, нормально к скату | 350 мм | 450 мм |', '| Площадка антресоли | 300 мм | 400 мм |', '| Квадратный мауэрлат | 150 × 150 мм | 200 × 200 мм |', '',
          'Габариты нужны для проверки пространства; несущая способность не рассчитана. Балки и отделка входят в общие толщины; выступы учитываются отдельно. Высота прохода 2050 мм сохраняется и при увеличенных толщинах. Предварительная ширина прохода — 1000 мм; проверять всю ширину, выход с лестницы, повороты и подходы к двум спальным местам. Высота нижнего помещения и отметка площадки будут выбраны при сравнении.', '',
          '## Экспликация', '', '| № | Помещение | Площадь, м² | Привязка |', '|---|---|---:|---|']
for room in spec['rooms']:
    lines.append(f"| {room['id']} | {room['name']} | {measurements[room['area']]['value']:.2f} | {room['placement'] or 'Не подтверждена; см. порядок проверки'} |")
lines += ['', 'Сумма площадей строк: 90,84 м², соответствует итогу. Размерные надписи отдельных геометрических участков собраны независимо от спорных названий.', '',
          '## Реестр размеров', '', 'Обозначения: «подписан» — числовая надпись PDF; «восстановлен» — предварительная оценка; «согласован» — PRD. Диапазоны обозначают сценарии проверки, а не строительные допуски.', '',
          '| ID | Размер / параметр | Значение | Источник | Статус | Диапазон |', '|---|---|---:|---|---|---|']
for item in spec['measurements']:
    source = item['source'] + (f", стр. {item['page']}" if item['page'] else '')
    bounds = item['check_range']
    value = 'не определено' if item['value'] is None else f"{item['value']} {item['unit']}"
    interval = '—' if bounds is None else str(bounds[0]) if bounds[0] == bounds[1] else f'{bounds[0]}–{bounds[1]}'
    lines.append(f"| {item['id']} | {item['label']} | {value} | {source} | {labels[item['status']]} | {interval} |")
lines += ['', 'Причины неизвестных значений и способ оценки неподписанных проёмов сохранены в полях `reason` реестра.', '',
          '## Источники', '', 'Исходные имена сохранены. SHA-256 записаны в JSON; проверка обнаруживает отсутствующий или изменённый файл. Дополнительный PNG сохранён отдельно по роли от двух основных референсов.', '']
for source in spec['sources']:
    lines.append(f"- `{source['path']}` — {source['role']}.")
lines += ['', '## Приёмка', '',
          '- 8 тестов стандартного Python пройдены: перевод 1000/5000/5300/−600 мм, корректный реестр, ошибочные единицы, пропавший/изменённый источник, неизвестный размер без причины, неверный диапазон и повтор номера помещения.',
          '- Red: те же тесты сначала завершились ошибками NotImplementedError в ещё не реализованных функциях; Green: после реализации все прошли.',
          '- Проверка сцены сначала отклонила заводскую сцену с кубом, без коллекций и связи с данными. После создания шаблона сохранённый файл открыт отдельным процессом и прошёл проверку.',
          f"- Проверено {data_check['source_count']} источников, {data_check['measurement_count']} параметров и {data_check['room_count']} записей экспликации. JSON прочитан с диска.",
          '- Сцена: METRIC, scale_length=1, METERS; 0 объектов; 7 основных коллекций и 4 подколлекции крыш; относительный путь к JSON разрешается, контрольная сумма совпадает.',
          '- Все три страницы PDF просмотрены визуально; это ручная проверка источника, не автоматический тест геометрии. Геометрия дома и рендеры на этом этапе отсутствуют.',
          '- Повторная генерация проверена. При изменении .blend вручную скрипт откажется его заменять по несовпадению контрольной суммы; другие сцены и исходники не затрагиваются.', '',
          '## Повторный запуск', '',
          'Нужны Python 3.9+ (стандартная библиотека) и Blender 5.2.1 LTS. Для повторного извлечения PDF использованы Poppler `pdftotext` и `pdftoppm`; для приведённых ниже проверок Poppler не нужен. Команды выполняются из корня проекта.', '',
          '```sh', 'python3 -m unittest discover -s tests -v', 'python3 scripts/stage1.py',
          '"/Applications/Blender.app/Contents/MacOS/Blender" --background --factory-startup --offline-mode --python-exit-code 1 --python scripts/blender_stage1.py -- create',
          '"/Applications/Blender.app/Contents/MacOS/Blender" --background --offline-mode models/house_stage1.blend --python-exit-code 1 --python scripts/blender_stage1.py -- verify',
          'python3 scripts/report_stage1.py', '```', '',
          'В этой среде Blender запускается вне sandbox: в sandbox ранее обнаружен сбой инициализации Metal. Используется отдельный фоновый процесс, открытые пользовательские сессии не меняются. Повторный запуск заменяет только неизменённый с момента генерации шаблон этапа 1. Ручные правки сохранять в другом .blend для этапа 2.', '',
          'После изменения PRD или исходников необходимо заново сверить реестр и осознанно обновить контрольные суммы; скрипты намеренно не принимают изменённые источники автоматически. Затем повторить проверки, генерацию и открытие сцены.', '',
          'Документация API: https://docs.blender.org/api/current/bpy.types.UnitSettings.html и https://docs.blender.org/api/current/bpy.ops.wm.html; проверена через Context7 при подготовке плана и фактическим запуском установленной версии.', '']
(ROOT / 'data/stage1_report.md').write_text('\n'.join(lines))
print('Report rebuilt from validated JSON and saved scene')
